INSERT INTO psppv2_form_assets (key, label, content_type, bytes, data_b64, source_url, updated_at) SELECT 'contract-ccmc-saveahead-2027', 'Boudoir Session Contract - Save-Ahead Offer', 'text/markdown', octet_length(t.txt), replace(encode(convert_to(t.txt,'UTF8'),'base64'), chr(10), ''), 'derived from contract-ccmc-2027 (calendar section removed), approved by Jessica 2026-10-25', now() FROM (SELECT replace(replace(replace(replace(replace(convert_from(decode(g.data_b64,'base64'),'UTF8'), ('The Session Fee of $99 for the Charity Calendar Model Call is imposed'), ('The Session Fee of $99 for the Save-Ahead Offer is imposed')), ('published on the Charity Calendar Model Call landing page for the Client''s review prior to booking'), ('published on the Save-Ahead Offer page and the booking menu for the Client''s review prior to booking')), ('CHARITY CALENDAR MODEL CALL:  ' || chr(10) || 'The Charity Calendar Model Call shall only include the $99 Session Fee and $500 off the Client''s collection, already applied to the collection prices shown at booking.  No products or services are included with the model call.  All other products must be purchased separately.' || chr(10) || '2027 CHARITY CALENDAR ENTRY:' || chr(10) || 'Entering the Client''s images in the 2027 Charity Calendar is optional and is decided by the Client at her Image Reveal & Ordering Appointment. Calendar entry requires the Client to sign the Photographer''s standard Model Release at or after the Image Reveal & Ordering Appointment. The $500 discount applies whether or not the Client''s images are entered in the calendar. Only sessions held through October 2027 are eligible for the calendar' || chr(59) || ' sessions held November 2027 through March 2028 receive the same Charity Calendar Model Call pricing but are not eligible for the calendar. No images will be shared publicly without the Client''s written permission.'), ('SAVE-AHEAD OFFER:  ' || chr(10) || 'The Save-Ahead Offer shall only include the $99 Session Fee and $500 off the Client''s collection, already applied to the collection prices shown at booking, for a session held through March 2028.  No products or services are included with the offer.  All other products must be purchased separately.')), ('with this Charity Calendar Model Call is $750'), ('with this Save-Ahead Offer is $750')), ('I understand the Charity Calendar Model Call only includes the $99 Session Fee I paid to reserve my date and $500 off my collection, already taken off every collection price. No products or services are included with the model call, and all other products must be purchased separately.*' || chr(10) || 'I understand that entering my images in the 2027 Charity Calendar is optional and is decided at my Image Reveal & Ordering Appointment, that it requires me to sign the standard Model Release, and that my $500 discount applies whether or not my images are entered. Sessions held after October 2027 are not eligible for the calendar, and my images will never be shared publicly without my written permission.*'), ('I understand the Save-Ahead Offer only includes the $99 Session Fee I paid to reserve my date and $500 off my collection, already taken off every collection price. No products or services are included with the offer, and all other products must be purchased separately.*')) AS txt FROM psppv2_form_assets g WHERE g.key='contract-ccmc-2027') t RETURNING key, bytes, md5(convert_from(decode(data_b64,'base64'),'UTF8')) AS m